 const { useState, useRef } = React;

 function ContactForm() {
     const [name, setName] = useState('');
     const [email, setEmail] = useState('');
     const [phone, setPhone] = useState('');

     const [errors, setErrors] = useState({});

     const nameRef = useRef(null);
     const emailRef = useRef(null);
     const phoneRef = useRef(null);

     const validate = () => {
         const newErrors = {};

         if (!name.trim()) {
             newErrors.name = 'Error: Full name is required.';
         }

         if (!email.trim()) {
             newErrors.email = 'Error: Email address is required.';
         } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
             newErrors.email = 'Error: Enter a valid email address like name@example.com.';
         }

         if (phone.trim() && !/^\+?[0-9\s\-()]{7,20}$/.test(phone)) {
             newErrors.phone = 'Error: Enter a valid phone number format (e.g., +1 555-555-5555).';
         }

         setErrors(newErrors);
         return newErrors;
     };

     const handleSubmit = (e) => {
         e.preventDefault();
         const newErrors = validate();

         if (Object.keys(newErrors).length > 0) {
             // Focus the first invalid field
             if (newErrors.name) {
                 nameRef.current.focus();
             } else if (newErrors.email) {
                 emailRef.current.focus();
             } else if (newErrors.phone) {
                 phoneRef.current.focus();
             }
         } else {
             alert('Form submitted successfully!');
             setName('');
             setEmail('');
             setPhone('');
             setErrors({});
         }
     };

     return (
         <div className="form-container">
             <h1>Contact Support</h1>
             <p>Required fields are marked with an asterisk (<span aria-hidden="true">*</span>).</p>
             <form onSubmit={handleSubmit} noValidate>
                 <div className="form-field">
                     <label htmlFor="name">Full name <span aria-hidden="true">*</span></label>
                     <input
                         id="name"
                         name="name"
                         type="text"
                         required
                         autoComplete="name"
                         value={name}
                         onChange={(e) => setName(e.target.value)}
                         aria-invalid={!!errors.name}
                         aria-describedby={errors.name ? 'name-error' : undefined}
                         ref={nameRef}
                     />
                     {errors.name && <p id="name-error" className="error-text">{errors.name}</p>}
                 </div>

                 <div className="form-field">
                     <label htmlFor="email">Email address <span aria-hidden="true">*</span></label>
                     <input
                         id="email"
                         name="email"
                         type="email"
                         required
                         autoComplete="email"
                         value={email}
                         onChange={(e) => setEmail(e.target.value)}
                         aria-invalid={!!errors.email}
                         aria-describedby={errors.email ? 'email-error' : undefined}
                         ref={emailRef}
                     />
                     {errors.email && <p id="email-error" className="error-text">{errors.email}</p>}
                 </div>

                 <div className="form-field">
                     <label htmlFor="phone">Phone number (optional)</label>
                     <input
                         id="phone"
                         name="phone"
                         type="tel"
                         autoComplete="tel"
                         value={phone}
                         onChange={(e) => setPhone(e.target.value)}
                         aria-invalid={!!errors.phone}
                         aria-describedby={`phone-help ${errors.phone ? 'phone-error' : ''}`.trim()}
                         ref={phoneRef}
                     />
                     <p id="phone-help" className="help-text">Format: +1 555-555-5555</p>
                     {errors.phone && <p id="phone-error" className="error-text">{errors.phone}</p>}
                 </div>

                 <button type="submit">Submit support request</button>
             </form>
         </div>
     );
 }

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<ContactForm />);
